<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateVersion\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\ValueObject\TemplateVersionSubjectVO;

trait TemplateVersionSubjectAttributeHolder
{
    protected TemplateVersionSubjectVO|string|null $subject = null;
    protected bool $subjectAssigned = false;

    public function getSubjectOrDefault(?TemplateVersionSubjectVO $subject): ?TemplateVersionSubjectVO
    {
        return $this->subjectAssigned ? ($this->subject !== null ? TemplateVersionSubjectVO::from($this->subject) : null) : $subject;
    }
    public function subject(TemplateVersionSubjectVO|string|null $subject): static
    {
        $this->subject = $subject;
        $this->subjectAssigned = true;
        return $this;
    }
    public function getSubject(): ?string
    {
        return $this->subject instanceof TemplateVersionSubjectVO ? $this->subject->value() : $this->subject;
    }
    public function isSubjectAssigned(): bool
    {
        return $this->subjectAssigned;
    }
    public function writeSubjectTo(mixed $att): void
    {
        if ($this->subjectAssigned) {
            $att->subject($this->subject);
        }
    }
    public function readSubjectFrom(mixed $att): void
    {
        if ($att->isSubjectAssigned()) {
            $subject = $att->getSubject();
            $this->subject($subject);
        }
    }
    public function unsetSubject(): static
    {
        $this->subjectAssigned = false;
        return $this;
    }
    protected function withDefaultSubject(): void
    {
    }
    protected function withAssertedSubjectRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->subjectAssigned = $this->subjectAssigned) {
            $value->subject = TemplateVersionSubjectVO::tryFrom($this->subject, $errorsList);
        }
    }
}
